import uuid

from pydantic import BaseModel, ConfigDict, Field


class Skill(BaseModel):
    """Skill data sent by the client; the id is generated by the server."""

    name: str = Field(min_length=1)
    level: int = Field(ge=1, le=5, description="1 = beginner, 5 = expert")
    years: float | None = Field(default=None, ge=0, le=50)


class SkillRead(Skill):
    """Skill returned by the API, including its id."""

    # Allows building from ORM objects: SkillRead.model_validate(skill_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
